def check_regression(current, baseline, tolerance=0.05):
    """Return the metrics that fell by more than tolerance below the baseline, or are missing."""
    eps = 1e-9   # absorbs floating-point error; far below one case on any real golden set
    return [m for m, base in baseline.items()
            if current.get(m) is None or base - current[m] > tolerance + eps]
